# Viva — slot D7 (part B): genodermatoses (8 cases)
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — genodermatoses chapter (define and classify
# genodermatoses, tuberous sclerosis criteria, shagreen patch, adenoma sebaceum, prenatal diagnosis, multiple tumour
# syndromes, neurocutaneous syndromes, NF, DNA-repair disorders, genetic counselling, mosaicism, Hailey–Hailey,
# Darier's, PXE), xeroderma pigmentosum; facts checked with IADVL 5e and 2012/2021 TSC and NF1 criteria.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Acrokeratosis verruciformis of Hopf", src=f"{PYQ}; {IA} (Genodermatoses — ATP2A2 spectrum)",
 qa=[
 ("What is acrokeratosis verruciformis of Hopf (AKV)?", ["Rare autosomal dominant genodermatosis (ATP2A2 — SERCA2 calcium pump, allelic with Darier's disease) presenting in childhood with multiple flat-topped, skin-coloured, wart-like papules on the dorsa of hands and feet, knees, elbows; may coexist with Darier's disease"]),
 ("Clinical features.", ["Small (1–5 mm) polygonal flat warty papules, punctate keratoses and pits on palms/soles, nail changes (thickening, longitudinal ridging, leukonychia); asymptomatic; persists lifelong"]),
 ("Histopathology.", ["Hyperkeratosis, hypergranulosis, acanthosis and papillomatosis with circumscribed elevations resembling 'church spires'; no acantholysis or dyskeratosis (vs Darier's) and no koilocytes (vs warts)"]),
 ("Define and classify genodermatoses (PYQ).", ["Genodermatoses: inherited single-gene (or chromosomal) disorders with skin manifestations", "By inheritance: autosomal dominant (NF1, TSC, Darier's, Hailey–Hailey, AKV), autosomal recessive (XP, lamellar ichthyosis, Netherton, PXE), X-linked recessive (X-linked ichthyosis, Fabry, Menkes, Wiskott–Aldrich), X-linked dominant (incontinentia pigmenti, Goltz, CHILD, Conradi–Hünermann), mitochondrial, mosaic", "By system/pathway: disorders of keratinisation, blistering (EB), pigmentation, DNA repair (XP, Bloom, Cockayne, Rothmund–Thomson, trichothiodystrophy), connective tissue (PXE, Ehlers–Danlos, Marfan, cutis laxa), vascular, ectodermal dysplasias, tumour syndromes, neurocutaneous (phakomatoses), metabolic (porphyrias)"]),
 ("Differential diagnosis.", ["Plane warts (koilocytes, Koebner), seborrhoeic keratoses (stucco keratosis in elderly), Darier's disease (acral papules + seborrhoeic distribution), epidermodysplasia verruciformis, lichen planus, acrokeratoelastoidosis (marginal papules)"]),
 ("Management.", ["Benign; cryotherapy, shave/curettage, CO2/Er:YAG laser, topical retinoids/keratolytics; oral acitretin for extensive lesions; genetic counselling"]),
 ],
 spot=["Flat wart-like papules on dorsa of hands since childhood, 'church-spire' histology — AKV of Hopf (ATP2A2)"]),

dict(case="Darier's disease", src=f"{PYQ}; {IA} (Darier's disease)",
 qa=[
 ("What is Darier's disease (keratosis follicularis)?", ["Autosomal dominant genodermatosis due to ATP2A2 mutations (SERCA2 — sarco/endoplasmic reticulum Ca²⁺-ATPase) → impaired desmosome assembly → acantholysis and dyskeratosis; onset around puberty (10–20 y)"]),
 ("Clinical features.", ["Greasy, warty, red-brown keratotic papules in a seborrhoeic distribution — scalp margin, forehead, nasolabial folds, ears, central chest/back, flexures (may become vegetating and malodorous); itchy, worse with heat, sweat, UV and friction", "Acral: palmar pits/punctate keratoses, AKV-like papules on dorsa of hands", "Nails (diagnostic): longitudinal alternating red and white bands, V-shaped notching at the free edge, subungual hyperkeratosis", "Oral: cobblestone white papules on palate", "Neuropsychiatric associations: depression, bipolar disorder, epilepsy, intellectual disability; salivary gland obstruction", "Variants: segmental/linear (mosaic), haemorrhagic acral, comedonal, bullous"]),
 ("Histopathology.", ["Suprabasal acantholysis forming clefts (lacunae) with villi, dyskeratotic cells — corps ronds (large round cells with pyknotic nucleus and clear halo, in spinous/granular layers) and grains (small elongated dark cells in stratum corneum), column of parakeratosis over the clefts", "DIF negative (vs pemphigus)"]),
 ("Complications.", ["Secondary bacterial infection, Kaposi's varicelliform eruption (HSV), dermatophyte infections, malodour, social stigma"]),
 ("Differential diagnosis.", ["Seborrhoeic dermatitis, Hailey–Hailey (flexural, erosions, no nail bands), Grover's disease (transient acantholytic dermatosis — older men, trunk, transient), acanthosis nigricans, confluent and reticulated papillomatosis, AKV of Hopf, pemphigus vegetans, warts"]),
 ("Management.", ["Avoid triggers: heat, sweating, sun (sunscreen), friction; cool cotton clothing; antiseptic washes", "Topical: retinoids (tazarotene, adapalene), steroids (short courses), 5-FU, calcineurin inhibitors, antibiotics/antifungals for infections", "Systemic: acitretin 10–25 mg/day or isotretinoin (most effective); doxycycline for flares; antivirals for HSV; oral magnesium chloride (case reports)", "Procedures: CO2/Er:YAG laser ablation, dermabrasion, PDT, excision for localised hypertrophic areas; botulinum toxin for flexural sweat-induced flares"]),
 ],
 spot=["Greasy warty papules in seborrhoeic distribution + red/white nail bands with V-nicks — Darier's (ATP2A2)", "Corps ronds and grains"]),

dict(case="Hailey–Hailey disease", src=f"{PYQ}; {IA} (Hailey–Hailey disease)",
 qa=[
 ("Write short notes on Hailey–Hailey disease (PYQ).", ["Familial benign chronic pemphigus — autosomal dominant ATP2C1 mutation (SPCA1 — Golgi Ca²⁺/Mn²⁺ ATPase) → defective desmosome assembly → suprabasal acantholysis; onset in 3rd–4th decade"]),
 ("Clinical features.", ["Recurrent flaccid vesicles and erosions on erythematous base in intertriginous areas (neck, axillae, groin, perianal, submammary), with crusting, painful fissures ('cracked/ dried mud' or 'rhagades'), maceration and foul odour; worse with heat, sweat, friction, infection", "Nails: longitudinal white bands (asymptomatic); mucosa rarely involved", "Segmental/linear types (mosaic)"]),
 ("Histopathology.", ["Suprabasal and full-thickness acantholysis with partially attached keratinocytes giving a 'dilapidated brick wall' appearance, few dyskeratotic cells (fewer than Darier's), DIF negative"]),
 ("Differential diagnosis.", ["Intertrigo (candidal, bacterial, tinea — KOH/culture), pemphigus vegetans (DIF positive), Darier's disease, inverse psoriasis, erythrasma, contact dermatitis, impetigo, HSV"]),
 ("Management.", ["Avoid friction/heat/sweating, weight loss, loose clothing; treat secondary infections (antibiotics, antifungals, antivirals)", "Topical steroids, calcineurin inhibitors, antiseptics, calcitriol", "Oral: doxycycline/minocycline (anti-inflammatory), dapsone, acitretin, low-dose naltrexone (newer evidence), cyclosporine short-term, oral magnesium, glycopyrrolate (sweat)", "Botulinum toxin to reduce sweating in flexures", "Procedures: CO2/Er:YAG laser ablation, dermabrasion, PDT, excision with grafting for refractory localised disease"]),
 ("Differentiate Darier's and Hailey–Hailey diseases.", ["Darier's: ATP2A2 (SERCA2, ER), seborrhoeic areas + flexures, keratotic papules, nail red-white bands with V-notch, palmar pits, oral papules, neuropsychiatric associations; histology — prominent dyskeratosis (corps ronds, grains)", "Hailey–Hailey: ATP2C1 (SPCA1, Golgi), flexures only, vesicles/erosions/fissures, nails white bands only, no mucosa; histology — dilapidated brick wall, little dyskeratosis"]),
 ],
 spot=["Recurrent flexural erosions with fissures in adults with family history — Hailey–Hailey (ATP2C1)", "Dilapidated brick wall"]),

dict(case="Incontinentia pigmenti", src=f"{PYQ}; {IA} (Incontinentia pigmenti)",
 qa=[
 ("What is incontinentia pigmenti (IP, Bloch–Sulzberger)?", ["X-linked dominant multisystem genodermatosis due to IKBKG (NEMO) mutations (commonly exon 4–10 deletion) — lethal in males in utero (affected females; rare males with Klinefelter or mosaicism); skewed X-inactivation", "Defective NF-κB activation → keratinocyte apoptosis and inflammation along Blaschko's lines"]),
 ("Describe the stages.", ["Stage 1 — vesicular/inflammatory (birth–4 months): linear vesicles and bullae on erythematous base along Blaschko's lines on limbs/trunk, with blood eosinophilia", "Stage 2 — verrucous (2–6 months): linear warty keratotic plaques (limbs)", "Stage 3 — hyperpigmented (6 months–adolescence): swirling/whorled slate-grey to brown pigmentation along Blaschko's lines on trunk (not necessarily at earlier sites)", "Stage 4 — hypopigmented/atrophic (adolescence/adult): pale, hairless, anhidrotic linear streaks on calves", "Stages may overlap or be absent"]),
 ("Extracutaneous features.", ["Teeth (most common extracutaneous ~80%): hypodontia/anodontia, conical/peg teeth, delayed eruption", "Hair: vertex scarring alopecia, woolly hair; nails: dystrophy, painful subungual keratotic tumours (later life)", "Eyes (~35%): retinal vasculopathy, retinal detachment, strabismus, microphthalmia — urgent ophthalmology review and serial retinal exams in infancy", "CNS (~30%): seizures, intellectual disability, spastic paresis, microcephaly, stroke-like lesions", "Breast hypoplasia, supernumerary nipples"]),
 ("Histopathology by stage.", ["Stage 1: eosinophilic spongiosis with intraepidermal vesicles full of eosinophils, dyskeratotic cells", "Stage 2: hyperkeratosis, papillomatosis, dyskeratosis (whorls)", "Stage 3: marked pigment incontinence (dermal melanophages) — origin of the name", "Stage 4: atrophic epidermis, absent adnexa"]),
 ("Diagnostic criteria (Minić et al. 2014).", ["Major: typical skin lesions at any stage along Blaschko's lines", "Minor: dental, ocular, CNS anomalies, alopecia/woolly hair, nail abnormalities, palate anomalies, breast/nipple anomalies, multiple male miscarriages, typical histology", "With positive IKBKG mutation, any one major or minor criterion suffices"]),
 ("Differential diagnosis (stage-wise).", ["Stage 1: bullous impetigo, HSV, varicella, EB, bullous mastocytosis, LCH", "Stage 2: linear epidermal naevus, warts, lichen striatus", "Stage 3: linear and whorled naevoid hypermelanosis (no preceding stages), X-linked reticulate pigmentary disorder, Naegeli syndrome", "Stage 4: hypomelanosis of Ito, Goltz syndrome, linear morphoea"]),
 ("Management.", ["Skin: supportive, gentle wound care, prevent infection — lesions resolve spontaneously", "Multidisciplinary follow-up: ophthalmology (retinal exam at diagnosis and frequently in first year; laser photocoagulation), neurology (MRI if neurological signs), dental care, developmental assessment", "Genetic counselling: 50% risk to daughters; affected male pregnancies usually miscarry"]),
 ],
 spot=["Female infant with linear vesicles along Blaschko's lines + eosinophilia — IP stage 1 (NEMO)", "Peg teeth, retinal vasculopathy"]),

dict(case="Neurofibromatosis type 1", src=f"{PYQ}; {IA} (Neurofibromatosis); NIH 2021 revised diagnostic criteria",
 qa=[
 ("Define NF1 (von Recklinghausen disease).", ["Autosomal dominant neurocutaneous disorder (1 in 3000) due to loss-of-function NF1 gene mutations (17q11.2) encoding neurofibromin — a RAS-GTPase activating protein (tumour suppressor); ~50% new mutations; complete penetrance with variable expressivity"]),
 ("Revised NIH diagnostic criteria (2021).", ["≥2 of: ≥6 CALMs (>5 mm prepubertal, >15 mm postpubertal); axillary or inguinal freckling; ≥2 neurofibromas of any type or 1 plexiform; optic pathway glioma; ≥2 Lisch nodules or ≥2 choroidal abnormalities; distinctive osseous lesion (sphenoid wing dysplasia, anterolateral tibial bowing, pseudarthrosis of long bone); heterozygous pathogenic NF1 variant (≥50% VAF in normal tissue)", "Child of a parent meeting criteria needs only one feature"]),
 ("Describe the cutaneous features.", ["CALMs (first sign — infancy), freckling (Crowe's sign — axillary/inguinal, 3–5 years), cutaneous neurofibromas (soft, skin-coloured to violaceous, 'button-hole' sign — invaginate on pressure; appear at puberty, increase in pregnancy), subcutaneous neurofibromas (firm, along nerves, painful), plexiform neurofibromas (congenital, 'bag of worms', overgrowth, risk of malignant change), juvenile xanthogranulomas (with risk of JMML), naevus anaemicus, glomus tumours, pruritus"]),
 ("Systemic features and complications.", ["Eyes: Lisch nodules (iris hamartomas — >90% adults), optic pathway glioma (15% children — visual loss, precocious puberty)", "Skeletal: scoliosis, sphenoid wing dysplasia, tibial pseudarthrosis, short stature, macrocephaly, osteoporosis", "Nervous: learning disabilities/ADHD (~50%), epilepsy, aqueductal stenosis, brain tumours (gliomas), unidentified bright objects on MRI", "Vascular: hypertension (renal artery stenosis, phaeochromocytoma), moyamoya", "Malignancy: malignant peripheral nerve sheath tumour (MPNST — 8–13% lifetime; pain, rapid growth, hardening of plexiform neurofibroma), GIST, breast cancer (women <50), JMML, rhabdomyosarcoma, phaeochromocytoma"]),
 ("Classify neurofibromatosis.", ["NF1 (classic), NF2 (bilateral vestibular schwannomas — merlin, 22q; now called NF2-related schwannomatosis; few CALMs, cataracts, meningiomas), schwannomatosis (SMARCB1/LZTR1), segmental (mosaic) NF1, Legius syndrome (SPRED1 — CALMs + freckling, no neurofibromas)", "Riccardi classification (8 types) — historical"]),
 ("Histopathology of a neurofibroma.", ["Unencapsulated dermal tumour of loosely arranged spindle cells with wavy 'S-shaped' nuclei in a pale myxoid/collagenous stroma with mast cells; S100 positive (Schwann cells), CD34 fibroblasts"]),
 ("Management.", ["Multidisciplinary yearly review: skin, BP, growth, development, scoliosis, eyes (annual ophthalmology up to 8 y), neurology; MRI when symptomatic; genetic counselling (50% transmission)", "Cutaneous neurofibromas: excision, CO2 laser, electrodesiccation (cosmetic/symptomatic)", "Plexiform neurofibromas: selumetinib (MEK inhibitor — approved for symptomatic inoperable PN in children ≥2 y), mirdametinib (newer); surgery", "MPNST: wide excision, radiotherapy; whole-body MRI surveillance in high-risk; breast screening from 30 y in women"]),
 ("Describe neurocutaneous syndromes (PYQ).", ["Phakomatoses: NF1, NF2, tuberous sclerosis, Sturge–Weber, von Hippel–Lindau, ataxia-telangiectasia (oculocutaneous telangiectasia, ataxia, immunodeficiency, lymphoma; ATM), incontinentia pigmenti, hypomelanosis of Ito, neurocutaneous melanosis, PHACE, epidermal naevus syndromes, Klippel–Trenaunay, Wyburn-Mason"]),
 ],
 spot=["CALMs + axillary freckles + neurofibromas + Lisch nodules — NF1", "Button-hole sign", "Selumetinib for plexiform neurofibroma"]),

dict(case="Pseudoxanthoma elasticum", src=f"{PYQ}; {IA} (Disorders of elastic tissue)",
 qa=[
 ("What is pseudoxanthoma elasticum (PXE)?", ["Autosomal recessive multisystem disorder of ectopic mineralisation (calcification) and fragmentation of elastic fibres in skin, eyes (Bruch's membrane) and arteries — ABCC6 mutations (liver transporter; low plasma pyrophosphate — calcification inhibitor); ENPP1/GGCX in PXE-like disorders"]),
 ("Cutaneous features.", ["Onset in childhood/adolescence: small yellowish papules coalescing into cobblestoned 'plucked chicken skin' / 'Moroccan leather' plaques on the sides of the neck (first site), axillae, antecubital and popliteal fossae, groin, periumbilical (flexural areas); later lax redundant folds; oral mucosa (lower lip) yellow papules; perforating PXE (periumbilical, multiparous women)"]),
 ("Systemic features.", ["Eyes: angioid streaks (breaks in calcified Bruch's membrane — grey-brown lines radiating from optic disc), 'peau d'orange' fundus, choroidal neovascularisation → haemorrhage → central vision loss", "Cardiovascular: premature atherosclerosis, intermittent claudication (peripheral arterial disease), reduced pulses, hypertension, angina, MI, stroke; GI haemorrhage (gastric arteries), mitral valve prolapse"]),
 ("Histopathology.", ["Fragmented, clumped, curled and calcified elastic fibres in the mid and deep reticular dermis — highlighted by Verhoeff–van Gieson (elastic) and von Kossa (calcium) stains; perforation of elastic fibres in perforating PXE"]),
 ("Differential diagnosis.", ["PXE-like papillary dermal elastolysis, solar elastosis, cutis laxa, late-onset focal dermal elastosis, perforating calcific elastosis, D-penicillamine-induced elastosis, amyloidosis, xanthomas, lax skin syndromes, Buschke–Ollendorff syndrome, white fibrous papulosis of neck"]),
 ("Diagnostic criteria (Plomp 2010).", ["Major: characteristic skin lesions with histology (fragmented calcified elastic fibres); angioid streaks/peau d'orange (retina); two pathogenic ABCC6 mutations", "Minor: one ABCC6 mutation, PXE in a first-degree relative"]),
 ("Management.", ["No cure; multidisciplinary follow-up: annual eye examination (Amsler grid self-monitoring; intravitreal anti-VEGF — bevacizumab, ranibizumab, aflibercept for choroidal neovascularisation), cardiovascular risk control (no smoking, lipid/BP control, exercise), avoid contact sports (eye trauma), caution with aspirin/anticoagulants (GI bleeding)", "Dietary calcium in normal amounts; magnesium supplementation and etidronate (bisphosphonate — reduced arterial calcification in trial) under study", "Cosmetic: excision of lax skin folds (plastic surgery), fillers; genetic counselling"]),
 ],
 spot=["Plucked-chicken yellow papules on sides of neck + angioid streaks — PXE (ABCC6)", "Calcified fragmented elastic fibres (von Kossa)"]),

dict(case="Tuberous sclerosis complex", src=f"{PYQ}; {IA} (Tuberous sclerosis); 2021 International TSC Consensus diagnostic criteria",
 qa=[
 ("Define tuberous sclerosis complex (TSC).", ["Autosomal dominant multisystem disorder (1 in 6000) with hamartomas in skin, brain, kidneys, heart, lungs and eyes, due to mutations in TSC1 (hamartin, 9q34) or TSC2 (tuberin, 16p13 — more severe) → loss of inhibition of mTORC1 (mammalian target of rapamycin) → cell growth; ~2/3 de novo", "Classic Vogt triad: seizures, intellectual disability, facial angiofibromas (epiloia) — present in <50%"]),
 ("Describe the clinical features, criteria and diagnosis (PYQ) — 2021 criteria.", ["Major (11): hypomelanotic macules (≥3, ≥5 mm), angiofibromas (≥3) or fibrous cephalic plaque, ungual fibromas (≥2), shagreen patch, multiple retinal hamartomas, multiple cortical tubers and/or radial migration lines, subependymal nodules (≥2), subependymal giant cell astrocytoma (SEGA), cardiac rhabdomyoma, lymphangioleiomyomatosis (LAM), angiomyolipomas (≥2)", "Minor (5): 'confetti' skin lesions, dental enamel pits (>3), intraoral fibromas (≥2), retinal achromic patch, multiple renal cysts, non-renal hamartomas, sclerotic bone lesions", "Definite TSC: 2 major or 1 major + ≥2 minor features, or identification of a pathogenic TSC1/TSC2 variant; possible: 1 major or ≥2 minor (LAM + angiomyolipomas alone = need another feature)"]),
 ("Write a short note on adenoma sebaceum (facial angiofibromas) (PYQ).", ["Misnomer — they are angiofibromas (not sebaceous adenomas): symmetrical, smooth, red-pink, dome-shaped papules on nasolabial folds, cheeks and chin (sparing upper lip), appearing at 2–5 years and increasing at puberty; ~75–90% of TSC", "Histology: dermal fibrosis with stellate fibroblasts, dilated capillaries, absent elastic tissue, atrophic follicles", "Treatment: topical sirolimus (rapamycin 0.1–1%) — first line; PDL, CO2/Er:YAG laser ablation, shave excision, electrosurgery"]),
 ("Write a short note on the shagreen patch (PYQ).", ["Connective tissue naevus (collagenoma): irregular, slightly elevated, skin-coloured to yellowish-brown plaque with orange-peel ('pig-skin'/shagreen leather) surface, usually on the lumbosacral area; appears in early childhood (~50% of TSC)", "Histology: thickened, densely packed collagen bundles in dermis"]),
 ("Other skin signs.", ["Hypomelanotic macules (earliest sign — at birth; ash-leaf shape, polygonal 'thumbprint', confetti macules on limbs; best seen with Wood's lamp; poliosis)", "Fibrous cephalic plaque (forehead — yellowish-brown plaque, often first facial sign)", "Ungual fibromas (Koenen's tumours — periungual/subungual flesh-coloured papules after puberty, toenails > fingernails; longitudinal groove in nail)", "Intraoral (gingival) fibromas, dental enamel pits, molluscum pendulum, café-au-lait macules (not specific)"]),
 ("Systemic manifestations.", ["CNS: cortical tubers, subependymal nodules, SEGA (obstructive hydrocephalus), seizures (infantile spasms — West syndrome), intellectual disability, autism, TAND (TSC-associated neuropsychiatric disorders)", "Kidney: angiomyolipomas (bleeding — leading cause of death in adults), cysts (TSC2/PKD1 contiguous gene syndrome), renal cell carcinoma", "Heart: rhabdomyomas (fetal/neonatal — regress), arrhythmias (WPW)", "Lungs: lymphangioleiomyomatosis (women — pneumothorax, chylothorax), multifocal micronodular pneumocyte hyperplasia", "Eyes: retinal hamartomas ('mulberry'), achromic patches"]),
 ("Investigations and surveillance.", ["MRI brain (every 1–3 years until 25 y — SEGA), EEG, renal MRI (every 1–3 years), echocardiography and ECG (infancy), HRCT chest (women ≥18 y), ophthalmology, dental exam, neuropsychiatric assessment; genetic testing; examine parents"]),
 ("Management.", ["mTOR inhibitors: everolimus (SEGA, angiomyolipomas, refractory seizures), sirolimus (LAM; topical for angiofibromas)", "Vigabatrin for infantile spasms; other antiepileptics; epilepsy surgery", "Embolisation/nephron-sparing surgery for bleeding angiomyolipomas", "Skin: topical sirolimus, lasers, excision of ungual fibromas and shagreen patches if symptomatic", "Genetic counselling (50% risk; germline mosaicism in apparently unaffected parents)"]),
 ("Classify multiple tumour syndromes (PYQ).", ["With adnexal tumours: Cowden (trichilemmomas, acral keratoses, oral papillomas — PTEN; breast/thyroid/endometrial cancer), Muir–Torre (sebaceous neoplasms + visceral cancers — mismatch repair), Brooke–Spiegler/familial cylindromatosis (CYLD — cylindromas, spiradenomas, trichoepitheliomas), Birt–Hogg–Dubé (fibrofolliculomas, renal tumours, pneumothorax — FLCN), Gorlin (BCCs), Rombo, Bazex–Dupré–Christol", "With fibrous/neural/vascular tumours: TSC, NF1/NF2, Gardner (epidermoid cysts, osteomas, desmoids, colonic polyps — APC), MEN 2B (mucosal neuromas), Carney complex, Reed syndrome (multiple cutaneous and uterine leiomyomas + renal cell carcinoma — fumarate hydratase), blue rubber bleb, Maffucci"]),
 ],
 spot=["Facial angiofibromas + ash-leaf macules + shagreen patch + Koenen's tumours — tuberous sclerosis (mTOR)", "Topical sirolimus for angiofibromas; everolimus for SEGA/AML"]),

dict(case="Xeroderma pigmentosum", src=f"{PYQ}; {IA} (Disorders of DNA repair)",
 qa=[
 ("What is xeroderma pigmentosum (XP)?", ["Rare autosomal recessive disorder of nucleotide excision repair (NER) of UV-induced DNA damage (cyclobutane pyrimidine dimers, 6-4 photoproducts) — complementation groups XPA–XPG and variant (XPV — POLH, defective translesion synthesis); commoner with consanguinity (India, Middle East, Japan)"]),
 ("Clinical features.", ["Infancy: acute exaggerated sunburn on minimal exposure (in ~50% — XPA, XPB, XPD, XPF, XPG), photophobia", "Early childhood: freckling (lentigines) on sun-exposed skin by 2 years, xerosis, poikiloderma (atrophy, telangiectasia, mottled hyper/hypopigmentation)", "Skin cancers: >10,000-fold risk of NMSC before 20 years (median age of first NMSC ~9 y) and ~2000-fold melanoma risk; also tongue tip SCC", "Eyes: photophobia, conjunctivitis, keratitis, ectropion, corneal clouding, ocular surface tumours", "Neurological (~25%, XPA, XPD): progressive neurodegeneration — sensorineural deafness, microcephaly, areflexia, ataxia, intellectual decline; De Sanctis–Cacchione syndrome (XP + dwarfism, hypogonadism, severe neurological)", "Internal malignancies: CNS tumours, leukaemia, lung"]),
 ("Enumerate disorders caused by defective DNA repair (PYQ).", ["Xeroderma pigmentosum, Cockayne syndrome (cachectic dwarfism, photosensitivity without cancer, pigmentary retinopathy — ERCC6/8), trichothiodystrophy (brittle sulphur-deficient hair with tiger-tail banding under polarised light — PIBIDS), XP–Cockayne overlap, UV-sensitive syndrome, Bloom syndrome (BLM helicase — photosensitive malar telangiectatic erythema, short stature, immunodeficiency, cancers; high sister chromatid exchange), Rothmund–Thomson (RECQL4 — poikiloderma from infancy, sparse hair, skeletal defects, osteosarcoma), Werner syndrome (adult progeria — WRN), ataxia-telangiectasia (ATM), Fanconi anaemia, dyskeratosis congenita (telomere maintenance), Muir–Torre/Lynch (mismatch repair)"]),
 ("Write a short note on Rothmund–Thomson and Bloom syndromes (PYQ).", ["Rothmund–Thomson (poikiloderma congenitale): AR RECQL4; erythema and blistering of cheeks at 3–6 months spreading to extremities → poikiloderma, sparse hair/eyebrows, juvenile cataracts, short stature, radial ray defects, dental anomalies; osteosarcoma and skin cancers", "Bloom: AR BLM; growth retardation, narrow face, photosensitive butterfly telangiectatic erythema, CALMs, immunodeficiency, infertility, very high risk of leukaemia/lymphoma and other cancers early in life"]),
 ("Diagnosis.", ["Clinical; DNA repair assays — unscheduled DNA synthesis in cultured fibroblasts after UV, host-cell reactivation, comet assay; post-UV cell survival; molecular genetic testing for the complementation group; prenatal diagnosis possible"]),
 ("Management.", ["Rigorous lifelong UV protection: avoid daylight (night activities — 'children of the night'), UV-protective clothing, face shields, UV-blocking films on windows, broad-spectrum high-SPF sunscreens, sunglasses; vitamin D supplementation", "Skin surveillance every 3–6 months by dermatologist; early excision of premalignant/malignant lesions; field therapy (5-FU, imiquimod), PDT; oral retinoids (isotretinoin/acitretin) for chemoprevention; nicotinamide; T4 endonuclease V liposome lotion (experimental)", "Eye: methylcellulose drops, protective eyewear; neurological and audiological follow-up; genetic counselling", "Immune checkpoint inhibitors highly effective for advanced cancers in XP (high mutational burden)"]),
 ],
 spot=["Freckling and poikiloderma with multiple skin cancers in a child of consanguineous parents — XP (NER defect)", "Children of the night — strict UV protection"]),
]
